CREATE TABLE public.agent_memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, content text NOT NULL CHECK(length(trim(content)) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.agent_memories TO authenticated; GRANT ALL ON public.agent_memories TO service_role;
ALTER TABLE public.agent_memories ENABLE ROW LEVEL SECURITY;
CREATE POLICY memories_own ON public.agent_memories FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER agent_memories_updated BEFORE UPDATE ON public.agent_memories FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.agent_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), mime text NOT NULL, content text NOT NULL CHECK(length(content) BETWEEN 1 AND 100000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.agent_documents TO authenticated; GRANT ALL ON public.agent_documents TO service_role;
ALTER TABLE public.agent_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_own ON public.agent_documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER agent_documents_updated BEFORE UPDATE ON public.agent_documents FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.agent_routines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 100), goal text NOT NULL CHECK(length(goal) BETWEEN 1 AND 4000), interval_hours integer NOT NULL CHECK(interval_hours IN (24,168)), active boolean NOT NULL DEFAULT true, next_run_at timestamptz NOT NULL, lease_until timestamptz, last_error text, last_result text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.agent_routines TO authenticated; GRANT ALL ON public.agent_routines TO service_role;
ALTER TABLE public.agent_routines ENABLE ROW LEVEL SECURITY;
CREATE POLICY routines_own ON public.agent_routines FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.user_id=auth.uid()));
CREATE TRIGGER agent_routines_updated BEFORE UPDATE ON public.agent_routines FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.agent_routine_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), routine_id uuid NOT NULL REFERENCES public.agent_routines(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'running' CHECK(status IN('running','completed','failed')), result text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(routine_id,scheduled_at));
GRANT SELECT ON public.agent_routine_runs TO authenticated; GRANT ALL ON public.agent_routine_runs TO service_role;
ALTER TABLE public.agent_routine_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY routine_runs_read ON public.agent_routine_runs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER agent_routine_runs_updated BEFORE UPDATE ON public.agent_routine_runs FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE FUNCTION public.claim_agent_routines() RETURNS SETOF public.agent_routines LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.agent_routines SET lease_until=now()+interval '15 minutes' WHERE id IN (SELECT id FROM public.agent_routines WHERE active AND next_run_at<=now() AND (lease_until IS NULL OR lease_until<now()) ORDER BY next_run_at FOR UPDATE SKIP LOCKED LIMIT 3) RETURNING * $$;
REVOKE ALL ON FUNCTION public.claim_agent_routines() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_agent_routines() TO service_role;